css:
/* Certificate of completion — landscape A4, rendered by wkhtmltopdf.
 *
 * wkhtmltopdf runs an old WebKit: no flexbox gap, no CSS grid, no custom
 * properties, no oklch, and pseudo-elements are unreliable. Everything below is
 * hex, box-model and real elements, with one table for the footer row — the
 * only primitive that lays three columns out dependably there.
 *
 * The shape follows what a certificate conventionally carries: a framed field,
 * a display title, a presentation line, the recipient as the hero, the reason
 * for the award, a signature row, an issuer seal, and a verifiable ID. Serif is
 * used for the title and the name only; everything else stays on the product's
 * own sans, so it reads as a document from this app rather than a clip-art
 * award.
 */

.cert {
    box-sizing: border-box;
    width: 100%;
    min-height: 19.6cm;
    padding: 0.5cm;
    background-color: #FFFFFF;
    font-family: "Geist", "Inter", -apple-system, "Segoe UI", sans-serif;
    color: #16202E;
    -webkit-print-color-adjust: exact;
}

/* Two frames rather than one: a hairline just inside a heavier brand rule is
   what reads as engraved rather than as a box drawn around the text. */
.cert-frame {
    position: relative;
    box-sizing: border-box;
    min-height: 18.6cm;
    border: 2px solid #00A2F3;
    padding: 0.4cm;
}

.cert-inner {
    position: relative;
    box-sizing: border-box;
    min-height: 17.8cm;
    border: 1px solid #CFE7F7;
    padding: 1.1cm 1.9cm 3.9cm;
    text-align: center;
}

/* Corner ticks, drawn as two short rules each. They sit ON the brand frame and
   are the only ornament here — enough to say "document", not a border pattern
   that fights the type. */
.tick { position: absolute; background-color: #00A2F3; }
.tick-h { width: 1.5cm; height: 3px; }
.tick-v { width: 3px; height: 1.5cm; }
.tl-h, .tl-v { top: -2px; left: -2px; }
.tr-h, .tr-v { top: -2px; right: -2px; }
.bl-h, .bl-v { bottom: -2px; left: -2px; }
.br-h, .br-v { bottom: -2px; right: -2px; }

/* ------------------------------------------------------------------ header */
.cert-head { position: relative; height: 1.1cm; margin-bottom: 0.9cm; }

.cert-head-left {
    position: absolute;
    left: 0;
    top: 0;
    text-align: left;
}

.cert-head-right {
    position: absolute;
    right: 0;
    top: 0.12cm;
    text-align: right;
}

.cert-logo { height: 30px; vertical-align: middle; }
.cert-wordmark { height: 26px; vertical-align: middle; }

.cert-brand-name {
    display: inline-block;
    vertical-align: middle;
    margin-left: 8px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #16202E;
}

/* ------------------------------------------------------------------- title */
.cert-title {
    font-family: Georgia, "Times New Roman", serif;
    font-size: 30px;
    line-height: 1.1;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #16202E;
    margin-bottom: 0.3cm;
}

.cert-title-rule {
    width: 3.4cm;
    height: 3px;
    background-color: #00A2F3;
    margin: 0 auto 0.85cm;
}

.cert-lede {
    font-size: 13px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #7B8CA1;
    margin-bottom: 0.45cm;
}

.cert-name {
    font-family: Georgia, "Times New Roman", serif;
    font-size: 46px;
    line-height: 1.15;
    color: #16202E;
    margin-bottom: 0.3cm;
}

.cert-name-rule {
    width: 9cm;
    height: 1px;
    background-color: #D7DFE9;
    margin: 0 auto 0.6cm;
}

.cert-body {
    font-size: 15px;
    line-height: 1.75;
    color: #33455C;
    max-width: 16cm;
    margin: 0 auto;
}

.cert-course { font-weight: 600; color: #16202E; }

.cert-meta {
    margin-top: 0.35cm;
    font-size: 12px;
    letter-spacing: 0.05em;
    color: #7B8CA1;
}

/* -------------------------------------------------------------------- seal
   An issuer seal is the element that most separates a certificate from a
   letter, so it is built rather than borrowed: a brand disc, a hairline inner
   ring, the mark, and two notched ribbon tails behind it. The tails are box-
   model triangles, not transforms — wkhtmltopdf rotates unreliably. */
.seal { position: relative; width: 2.5cm; height: 3.3cm; margin: 0 auto; }

.rib {
    position: absolute;
    top: 1.55cm;
    width: 0.46cm;
    height: 1.68cm;
    background-color: #0784C4;
}
.rib-l { left: 0.69cm; }
.rib-r { left: 1.35cm; }

.rib-notch {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 0;
    border-left: 0.23cm solid transparent;
    border-right: 0.23cm solid transparent;
    border-bottom: 0.36cm solid #FFFFFF;
}

.seal-disc {
    position: absolute;
    top: 0;
    left: 0;
    width: 2.5cm;
    height: 2.5cm;
    border-radius: 50%;
    background-color: #00A2F3;
}

.seal-ring {
    position: absolute;
    top: 0.15cm;
    left: 0.15cm;
    width: 2.2cm;
    height: 2.2cm;
    border-radius: 50%;
    border: 1px solid #9BDBFF;
}

.seal-mark {
    position: absolute;
    top: 0.72cm;
    left: 0.86cm;
    width: 0.78cm;
    height: 0.98cm;
}

.seal-caption {
    margin-top: 0.12cm;
    font-size: 8px;
    font-weight: 600;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: #7B8CA1;
    text-align: center;
}

/* ------------------------------------------------------------------ footer */
/* The wrapper is what is positioned, not the table: an absolutely positioned
   <table> shrink-wraps its content in WebKit — `left` and `right` together do
   not stretch it — and the whole footer collapsed into the bottom-left corner. */
.cert-foot-wrap {
    position: absolute;
    left: 1.9cm;
    right: 1.9cm;
    bottom: 1.15cm;
}

.cert-foot { width: 100%; border-collapse: collapse; }

.cert-foot td {
    width: 33.33%;
    vertical-align: bottom;
    padding: 0;
    text-align: center;
}

.cert-foot-label {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: #8496AB;
    margin-bottom: 3px;
}

.cert-foot-value { font-size: 13px; font-weight: 600; color: #16202E; }

.cert-foot-line {
    height: 1px;
    background-color: #D7DFE9;
    margin: 0 0.4cm 7px;
}

.cert-verify {
    margin-top: 0.5cm;
    padding-top: 0.28cm;
    border-top: 1px solid #EDF1F6;
    font-size: 10px;
    color: #8496AB;
    text-align: center;
}

.cert-id {
    font-family: "SFMono-Regular", "Menlo", "Consolas", monospace;
    font-size: 10px;
    letter-spacing: 0.04em;
    color: #33455C;
}
